export type FeedKey = keyof typeof FEED_IDS;
export type Asset = "BTC" | "ETH";
export type Timeframe = "1m" | "5m" | "10m" | "15m";

export const TIMEFRAMES: Timeframe[] = ["1m", "5m", "10m", "15m"];

export function feedKey(asset: Asset, tf: Timeframe): FeedKey {
  return `${asset}-${tf}` as FeedKey;
}

